bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync,existsSync,statSync} from 'node:fs';
import pg from 'pg';
import {readPrivateToken} from '/opt/videobot/src/runtime/config.mjs';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
const e=process.env;
const dburl=e.VIDEOBOT_DATABASE_URL_FILE?readPrivateToken(e.VIDEOBOT_DATABASE_URL_FILE):'postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim())+'@'+e.VIDEOBOT_DB_HOST+':5432/videobot';
const pool=new pg.Pool({connectionString:dburl,max:1,connectionTimeoutMillis:5000});
const net=createCreatorTelegramFetch(globalThis.fetch);
let code=0;
try{
const qr=await pool.query("SELECT l.paid_video_file_id,l.rights_verified,l.adult_consent_verified,l.price_stars,r.topic_id FROM videobot_post_receipts r JOIN videobot_listings l ON r.listing_id=l.listing_id WHERE r.paid_message_id=4715 AND r.status='sent'");
if(qr.rowCount!==1||qr.rows[0].rights_verified!==true||qr.rows[0].adult_consent_verified!==true||qr.rows[0].price_stars!==10||Number(qr.rows[0].topic_id)!==1695)throw Object.assign(Error('ORIGINAL_CONSENT_OR_TOPIC_MISMATCH'),{code:61});
const base=e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org';
if(base.includes('api.telegram.org'))throw Object.assign(Error('CLOUD_API_1487MB_UPLOAD_UNSUPPORTED'),{code:62});
const token=readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE);
const result=await net.fetch(base+'/bot'+token+'/getFile',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({file_id:qr.rows[0].paid_video_file_id}),signal:AbortSignal.timeout(20000)}).then(r=>r.json());
if(!result.ok)throw Object.assign(Error('LOCAL_GETFILE_NOT_AVAILABLE'),{code:63});
const path=String(result.result?.file_path??'');
if(!path.startsWith('/')||!existsSync(path))throw Object.assign(Error('VIDEO_FILE_NOT_MOUNTED_IN_BOT_CONTAINER'),{code:64});
const s=statSync(path);
if(!s.isFile()||s.size<1300000000||s.size>2000000000)throw Object.assign(Error('SOURCE_VIDEO_SIZE_MISMATCH'),{code:65});
console.log('FRESH_UPLOAD_SOURCE_LOCAL=PASS;SOURCE_SIZE_BYTES='+s.size+';OFFICIAL_API=LOCAL;TARGET_THREAD=1695');
}catch(err){code=err.code||66;console.log('FRESH_UPLOAD_PREFLIGHT='+String(err.message).slice(0,100));}finally{await pool.end().catch(()=>{});await net.close().catch(()=>{});}
process.exitCode=code;
JS
